import sys

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    k = int(data[1])

    def query(c):
        print(f"? {c}")
        sys.stdout.flush()
        return input().strip()

    def reset():
        print("R")
        sys.stdout.flush()

    # Initialize the set of distinct coffee varieties
    distinct_varieties = set()

    # First pass: Identify all unique varieties
    for i in range(1, n + 1):
        if query(i) == 'Y':
            distinct_varieties.add(i)

    # Reset memory
    reset()

    # Second pass: Verify the distinct varieties
    for variety in list(distinct_varieties):
        found = False
        for i in range(1, n + 1):
            if query(i) == 'Y' and i != variety:
                found = True
                break
        if not found:
            distinct_varieties.remove(variety)

    # Output the result
    print(f"! {len(distinct_varieties)}")

if __name__ == "__main__":
    main()
